(()=>{const $=s=>document.querySelector(s),app=$('#app'),keys=['gate5_current_scene','gate5_game_time','gate5_concept_legal_reservation','gate5_concept_clarity','gate5_concept_proportionality','gate5_concept_due_process','gate5_run_result','gate5_complete','gate5_attempts'];
const q=[{id:'legal_reservation',title:'面對這項限制，現在最先需要確認的是什麼？',a:['被查看手機後能不能提出救濟','「治安事件」適用範圍清不清楚','有沒有法律或法律授權作為依據','查看手機對治安有沒有實際效果'],ok:2,hint:'再想一下：在討論限制重不重、規定清不清楚，或之後能不能救濟之前，最前面要先確認什麼？',ex:'限制人民基本權，原則上應有法律依據，或有法律授權。',memory:'請問你們這樣做的依據是什麼？',name:'法律保留'}, {id:'clarity',title:'這種情況最可能造成什麼問題？',a:['人民難以預先判斷自己何時可能被盤查','警方完全不能使用「行跡可疑」這種文字','只要有法律依據，執法標準不同也沒關係','只要盤查時間不長，就不會有基本權問題'],ok:0,hint:'先想想：真正讓人無法預先判斷的，是不是「哪些行為會被算作行跡可疑」？',ex:'法律可以使用抽象或不確定法律概念；但規範仍應讓人民能合理理解、預見，並使執法受到可確認的標準拘束。',memory:'所以，到底什麼情況才算？',name:'法律明確性'}, {id:'proportionality',title:'如果要進一步判斷哪一種措施比較適當，還最需要知道什麼？',a:['被盤查者事後能不能提出救濟','「具體異常行為」是否有明確標準','全面安檢是否具有法律依據','各方案對隱私、行動自由等權利影響多大'],ok:3,hint:'目前已知道各方案都有一定治安效果，也知道通行時間。接下來還缺哪一塊，才能比較「效果」與「人民付出的代價」？',ex:'比較政策時，也需要判斷對隱私、行動自由等基本權的限制程度。',memory:'有沒有別的方法，可以少限制一點？',name:'比例原則'}, {id:'due_process',title:'從目前處理過程來看，最需要補上的保障是什麼？',a:['讓當事人知道具體理由，並有適當機會說明及尋求救濟','再確認處罰金額是否與治安目的相稱','重新確認「拒絕配合」的意思是否清楚','先確認這項裁罰是否具有法律依據'],ok:0,hint:'現在先不要看處罰金額重不重，也不是只問法源。想想看：當事人連政府為什麼這樣認定都不知道，最缺少的是什麼？',ex:'國家作成影響人民權利的重要不利決定時，應依事件性質提供相應的程序保障。',memory:'我可以先知道理由，也說明我的情況嗎？',name:'正當法律程序'}];
let S=load();function load(){let x={scene:'start',time:1300,attempts:{},concepts:{}};keys.forEach(k=>{let v=localStorage.getItem(k);if(v!==null){if(k==='gate5_current_scene')x.scene=v;else if(k==='gate5_game_time')x.time=+v;else if(k==='gate5_attempts')x.attempts=JSON.parse(v);else if(k.startsWith('gate5_concept_'))x.concepts[k.replace('gate5_concept_','')]=v==='true';else x[k.replace('gate5_','')]=v}});return x}function save(){localStorage.setItem('gate5_current_scene',S.scene);localStorage.setItem('gate5_game_time',S.time);localStorage.setItem('gate5_attempts',JSON.stringify(S.attempts));Object.entries(S.concepts).forEach(([k,v])=>localStorage.setItem('gate5_concept_'+k,v));['run_result','complete'].forEach(k=>S[k]!==undefined&&localStorage.setItem('gate5_'+k,S[k]))}function restart(){keys.forEach(k=>localStorage.removeItem(k));S=load();render()}function t(){return `${String(Math.floor(S.time/60)).padStart(2,'0')}:${String(S.time%60).padStart(2,'0')}`}function advance(n){let old=t();S.time+=n;save();return `<span class="clock-tick">${old} → ${t()}</span>`}function shell(content,{hud=true}={}){return `${hud?`<div class="street"></div><header class="hud"><div>現在時間｜<span class="time">${t()}</span><br>末班車｜22:30</div><button class="restart" data-act="restart">重新開始本關</button></header>`:''}${content}`}function btn(label,act,extra=''){return `<button class="choice" data-act="${act}" ${extra}>${label}</button>`}function go(s){S.scene=s;save();render()}function story(title,body,buttons){app.innerHTML=shell(`<div class="scene-title"><b>${title}</b><span>GATE 5｜規則失控夜</span></div><div class="stage"><div class="paper">${body}<div class="choices">${buttons}</div></div></div>`);bind()}function bind(){app.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>action(b.dataset.act));}
function action(a){if(a==='restart')return restart();if(a==='start')return go('intro');if(a==='intro')return go('act1');if(a.startsWith('choice')){let [_,act,n]=a.match(/choice(\d)(\d)/);let mins=[[1,4,7],[1,3,4],[1,2,3],[1,2,3]][act-1][n];S.lastAdvance=advance(mins);return go('quiz'+act)}if(a==='special2'){S.lastAdvance=advance(2);return go('quiz2')}if(a.startsWith('answer'))return answer(...a.match(/answer(\d)(\d)/).slice(1).map(Number));if(a==='results')return go('results');if(a.startsWith('policy')){S.policy=a.slice(-1);return go('policyresults')}if(a.startsWith('keep'))return go('quiz3');if(a==='proportion')return go('proportion');if(a==='fine')return go('quiz4');if(a==='run')return runner();if(a.startsWith('lane'))return lane(a);if(a==='summary')return go('summary');if(a==='final')return go('final');if(a.startsWith('finala'))return finalAnswer(+a.slice(-1));}
function secondHint(item){let hints={legal_reservation:'先把問題拉回「國家憑什麼能做這件事」：其他問題都要在這個前提確認後才適合繼續討論。',clarity:'聚焦在一般人事先能不能理解、預見哪些行為會被納入判斷；不是要禁止法律使用抽象文字。',proportionality:'把三種方案放在一起比較：還缺少哪一項資訊，才能判斷治安效果與人民付出的代價是否相稱？',due_process:'注意通知本身缺少的內容：當事人是否知道政府根據哪些具體事實作成決定，也有沒有機會說明或救濟？'};return hints[item.id]||item.hint}function answer(num,choice){let item=q[num-1],tries=S.attempts[item.id]||0;S.attempts[item.id]=tries+1;if(choice===item.ok){S.concepts[item.id]=true;save();return afterQuiz(num,`<div class="hint"><b>答對了。</b><br>正確答案：${'ABCD'[item.ok]}｜${item.a[item.ok]}<br>解析：${item.ex}</div><p class="memory">你記住了一句話：<br>「${item.memory}」</p><small>${item.name}</small>`)}S.concepts[item.id]=false;save();let hint=tries===0?item.hint:secondHint(item);return quiz(num,`<div class="hint"><b>這次還不是最合適的選項。</b><br>提示：${hint}</div>`)}function quiz(n,feedback=''){let item=q[n-1];story(`第${['一','二','三','四'][n-1]}幕`,`${S.lastAdvance?`<small>時間推進：${S.lastAdvance}</small>`:''}<h2>${item.title}</h2>${feedback}`,item.a.map((x,i)=>btn(`<b>${'ABCD'[i]}</b>${x}`,`answer${n}${i}`)).join(''));S.lastAdvance=''}function afterQuiz(n,more){if(n===1)return story('霧川站入口',`<p>旁邊乘客低聲說：「查看私人訊息，總要有依據吧？」</p>${more}`,btn('繼續前往中央街','next2'));if(n===2)return story('中央街管制區',`<p>警察甲：「我覺得一直看手機、站在這裡不走就值得注意。」</p><p>警察乙：「我通常要看到反覆徘徊、一直查看店面才會攔。」</p>${more}`,btn('繼續前進','next3'));if(n===3)return story('比較三種方案',`${more}<p>你將三種措施放進心裡比較。</p>`,btn('查看比例原則的三個問題','proportion'));return story('裁罰通知',`${more}<p>你收起手機，往霧川站方向快步走去。</p>`,btn('繼續趕路','run'))}
function render(){if(S.scene==='start')story('規則失控夜',`<h1>GATE 5</h1><p>康安高中放學後，你走在剛下過雨的霧川商圈。</p><div class="chat">家人：今天附近好像有事情，早點回家。</div><div class="chat">新聞推播：霧川商圈晚間發生暴力事件，警方擴大周邊治安管制。</div><p><b>末班車｜22:30</b></p><small>有些選擇，會讓今晚花掉更多時間。</small>`,btn('開始','start'));else if(S.scene==='intro')story('往霧川站',`<p>雨後的街道映著路燈。你加快腳步。</p>`,btn('抵達霧川站入口','act1'));else if(S.scene==='act1')act1();else if(S.scene==='quiz1')quiz(1);else if(S.scene==='quiz2')quiz(2);else if(S.scene==='quiz3')quiz(3);else if(S.scene==='quiz4')quiz(4);else if(S.scene==='results')results();else if(S.scene==='policyresults')policyresults();else if(S.scene==='proportion')proportion();else if(S.scene==='fine')fine();else if(S.scene==='summary')summary();else if(S.scene==='final')final();}
function act1(){story('第一幕｜霧川站',`<p>站務人員攔下你：「今晚附近有治安事件。進站前請先把手機解鎖，我們確認一下最近的訊息。」</p>`,btn('<b>A｜</b>直接配合','choice10')+btn('<b>B｜</b>先問清楚','choice11')+btn('<b>C｜</b>不想處理，離開入口','choice12'))}function act2(){let special=S.concepts.legal_reservation?btn('<b>✦｜</b>請問你依據什麼規定盤查我？','special2'):'';story('第二幕｜中央街',`<p>公告：「警方得對『行跡可疑之人』進行盤查。」</p><p>一名一直站在路旁看手機的路人被攔下；另一名情況相近者卻被放行。</p><p>警察對你說：「你先停一下，我覺得你有點可疑。」</p>`,btn('<b>A｜</b>直接配合','choice20')+btn('<b>B｜</b>問「我哪裡可疑？」','choice21')+btn('<b>C｜</b>直接拒絕','choice22')+special)}function results(){story('第三幕｜三種治安方案',`<p>警方提出三種虛構方案。請選擇一項先看其後果；這裡沒有唯一政策答案。</p>`,btn('<b>A｜</b>全面安檢','policyA')+btn('<b>B｜</b>針對具體異常者盤查','policyB')+btn('<b>C｜</b>增加街上警力、少直接干預','policyC'))}function policyresults(){let r={A:['人潮大排長龍','許多人被要求打開手機','治安事件明顯下降','所有人都受到高度檢查'],B:['人潮相對順暢','警方集中盤查少數具體異常者','治安改善幅度接近 A','仍有少數漏網風險'],C:['幾乎不直接干預一般路人','街上可見警力增加','治安仍有改善','改善幅度低於 A、B']} ;story('方案後果（皆為虛構資料）',`<p>你先看了方案 ${S.policy}：</p><ul class="result-list">${r[S.policy].map(x=>`<li>${x}</li>`).join('')}</ul><hr><small>接著快速播放其餘兩案：A、B、C 都有一定治安效果；差異也在通行、隱私與行動自由的代價。</small><p>看完結果後，你要維持原本選擇嗎？</p>`,btn('維持原選擇','keep')+btn('改選 A','keepA')+btn('改選 B','keepB')+btn('改選 C','keepC'))}function proportion(){story('比例原則',`<p>所有三種措施都對降低治安風險有幫助。</p><div class="proportion"><div class="principle"><b>適合性</b>手段是否有助於達成目的？效果比較弱，不代表沒有適合性。</div><div class="principle"><b>必要性</b>A：治安事件下降 40%；B：下降 35%，但只針對具體異常者。如果效果接近、少限制很多，還有必要使用更重手段嗎？</div><div class="principle"><b>衡量性</b>即使全面安檢能再多降低一些風險，要求所有人打開私人手機內容，額外公益與權利損害是否失衡？</div></div>`,btn('繼續前往霧川站','fine'))}function fine(){story('第四幕｜三萬元裁罰通知',`<div class="notice"><b>行政裁罰通知</b><p>系統紀錄顯示，你稍早曾「拒絕配合治安措施」。</p><p>處罰鍰：新臺幣 30,000 元。</p><small>遊戲中的虛構行政處分情境</small></div><p>通知沒有具體時間、地點、行為、完整事實理由或清楚救濟資訊。</p>`,btn('<b>A｜</b>先把通知關掉','choice30')+btn('<b>B｜</b>查看詳細內容','choice31')+btn('<b>C｜</b>要求進一步說明','choice32'))}function summary(){let defs=[['legal_reservation','法律保留','國家憑什麼可以限制人民？'],['clarity','法律明確性','人民能不能合理知道什麼情況會受到限制？'],['proportionality','比例原則','有必要做到這麼重嗎？'],['due_process','正當法律程序','國家作成重要決定的過程有沒有適當保障？']];let count=defs.filter(x=>S.concepts[x[0]]).length;story('今晚你掌握了幾種判斷方式？',`<h1>${count} / 4</h1><div class="cards">${defs.map(x=>S.concepts[x[0]]?`<div class="card"><b>${x[1]}</b><br>${x[2]}</div>`:`<div class="card lock">🔒<br>？？？</div>`).join('')}</div>`,btn('翻開今晚事件整理','final'))}function final(){app.innerHTML=shell(`<div class="stage"><div class="paper book"><h2>霧川商圈｜今晚事件整理</h2><section><h3>法律保留</h3><b>國家憑什麼限制人民？</b><br>限制基本權，原則上應有法律依據；若由法律授權行政機關進一步規範，也須符合授權要求。</section><section><h3>法律明確性</h3><b>人民能不能理解、預見規則？</b><br>法律可以使用抽象或不確定法律概念，但規範仍應使人民能合理理解、預見，並讓執法受到可確認的標準拘束。</section><section><h3>比例原則</h3><b>有必要做到這麼重嗎？</b><br>適合性：手段有助於目的嗎？<br>必要性：有沒有侵害較小、效果相近的方法？<br>衡量性：公益與權利損害是否失衡？</section><section><h3>正當法律程序</h3><b>國家做決定的過程有沒有適當保障？</b><br>國家作成影響人民權利的重要決定時，應依事件性質提供相應的程序保障，例如適當告知、表達意見與救濟機會。</section><button class="next" data-act="final">進入綜合題</button></div></div>`);bind()}function finalAnswer(c){let tries=S.finaltries||0;if(c===3||tries){S.complete=true;save();app.innerHTML=shell(`<div class="complete"><div class="paper"><h1>GATE 5 COMPLETE</h1><p>${c===3?'你完成了最後的整合判斷。':'正確答案：D。完整分析必須分別檢查法源、明確程度、手段是否過度，以及程序保障。'}</p><button class="next" data-act="restart">重新開始本關</button></div></div>`);bind()}else{S.finaltries=1;story('綜合題',`<h2>下列哪一項分析最完整？</h2><div class="hint">提示：不要只看其中一個問題；回想今晚每一幕分別檢查了什麼。</div>`,['只要政策目的是維護治安，就可以限制人民權利。','只要有內部通知，就不需要再確認法律依據。','只要規定寫得夠清楚，就不用考慮限制是否過度。','應分別檢查限制的法源、規範明確程度、手段是否過度，以及程序保障是否充分。'].map((x,i)=>btn(`<b>${'ABCD'[i]}</b>${x}`,'finala'+i)).join(''))}}
function runner(){S.scene='runner';save();let start=Date.now(),hits=0,split=false,done=false,margin=Math.max(26,Math.min(55,30+(2230-S.time)*3));app.innerHTML=shell(`<div class="runner"></div><div class="run-hud"><b>距離月台：380 公尺</b><b>末班車倒數：<span id="count">${margin}</span> 秒</b></div><div class="track"></div><div class="runner-person">🏃</div><div class="run-copy">點擊畫面或按 Space 跳躍<br>快跑！</div>`,{hud:false});let person=$('.runner-person');function jump(){person.classList.add('jump');setTimeout(()=>person.classList.remove('jump'),380)}function obs(){if(done)return;let o=document.createElement('div');o.className='obstacle';o.textContent=['▲','💧','🚲','🧳','▤','⚠'][Math.floor(Math.random()*6)];app.append(o);let check=setInterval(()=>{let r=o.getBoundingClientRect(),p=person.getBoundingClientRect();if(!person.classList.contains('jump')&&r.left<p.right&&r.right>p.left&&r.bottom>p.top){hits++;person.style.opacity='.4';setTimeout(()=>person.style.opacity='1',850);o.remove();clearInterval(check)}if(!document.body.contains(o))clearInterval(check)},70);setTimeout(obs,2100+Math.random()*1300)}obs();let timer=setInterval(()=>{let remaining=margin-(Date.now()-start)/1000;$('#count').textContent=Math.max(0,remaining).toFixed(1);if(!split&&Date.now()-start>16000){split=true;clearInterval(timer);return splitChoice()}if(remaining<=0)return finish(false)},100);function splitChoice(){let d=document.createElement('div');d.className='split';d.innerHTML=`<button class="lane" data-act="laneFast"><b>快速通道</b><br><small>配合臨時查驗，可直接通行</small></button><button class="lane" data-act="laneNormal"><b>一般通道</b><br><small>無須接受額外查驗，但需繞行</small></button>`;app.append(d);bind();setTimeout(()=>{if(document.body.contains(d)){d.remove();resume('normal')}},2800)}function resume(lane){if(lane==='fast')setTimeout(()=>$('.run-copy').textContent='快速查驗後，繼續跑！',700);else margin-=3;timer=setInterval(()=>{let remaining=margin-(Date.now()-start)/1000;$('#count').textContent=Math.max(0,remaining).toFixed(1);if(Date.now()-start>38000+hits*900)return finish(remaining>0);if(remaining<=0)finish(false)},100)}window._lane=resume;function finish(ok){if(done)return;done=true;clearInterval(timer);S.run_result=ok?'success':'failed';save();if(ok){app.innerHTML=shell(`<div class="complete"><div class="paper"><h1>GATE 5 CLEAR</h1><p>你衝進車門，列車開動。手機顯示：「我上車了。」</p><button class="next" data-act="summary">查看今晚的判斷方式</button></div></div>`);bind()}else{app.innerHTML=shell(`<div class="complete"><div class="paper"><h1>22:30</h1><p>末班車已離站。</p><div class="chat">家人：你怎麼還沒回來？</div><h2>任務失敗｜未能趕上末班車</h2><button class="next" data-act="restart">重新挑戰</button></div></div>`);bind()}}}function lane(a){if(window._lane){$('.split')?.remove();window._lane(a==='laneFast'?'fast':'normal')}}
document.addEventListener('keydown',e=>{if(e.code==='Space'&&S.scene==='runner'){e.preventDefault();$('.runner-person')?.classList.add('jump');setTimeout(()=>$('.runner-person')?.classList.remove('jump'),380)}});app.addEventListener('click',e=>{if(S.scene==='runner'&&!e.target.closest('button')){$('.runner-person')?.classList.add('jump');setTimeout(()=>$('.runner-person')?.classList.remove('jump'),380)}});let old=action;action=function(a){if(a==='next2'){S.lastAdvance=advance(12);return go('act2')}if(a==='next3'){S.lastAdvance=advance(13);return go('results')}if(a==='fine'){S.lastAdvance=advance(15);return go('fine')}if(/^choice3/.test(a))return old('choice4'+a.slice(-1));old(a)};const baseRender=render,knownScenes=new Set(['start','intro','act1','act2','quiz1','quiz2','quiz3','quiz4','results','policyresults','proportion','fine','summary','final']);render=function(){if(S.scene==='act2')return act2();if(!knownScenes.has(S.scene)){S.scene='start';save()}return baseRender()};render();})();
